package com.urlshortner.urls;

import java.security.SecureRandom;
import org.springframework.stereotype.Component;

@Component
public class CodeGenerator {
    private static final String ALPHABET = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    private final SecureRandom random = new SecureRandom();

    public String next() {
        char[] code = new char[8];
        for (int i = 0; i < code.length; i++) {
            code[i] = ALPHABET.charAt(random.nextInt(ALPHABET.length()));
        }
        return new String(code);
    }
}

package com.urlshortner.urls;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.method.HandlerMethod;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

@Configuration(proxyBeanMethods = false)
public class CreationLimitConfiguration implements WebMvcConfigurer {
    private final CreationRateLimiter limiter;

    public CreationLimitConfiguration(CreationRateLimiter limiter) {
        this.limiter = limiter;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new HandlerInterceptor() {
            @Override
            public boolean preHandle(HttpServletRequest request, HttpServletResponse response,
                    Object handler) {
                if (handler instanceof HandlerMethod method
                        && UrlController.class.isAssignableFrom(method.getBeanType())
                        && method.getMethod().getName().equals("create")
                        && method.getMethod().getParameterCount() == 1
                        && method.getMethod().getParameterTypes()[0] == UrlController.CreateRequest.class) {
                    limiter.admit();
                }
                return true;
            }
        });
    }
}

package com.urlshortner.urls;

import java.util.Objects;
import java.util.function.LongSupplier;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

@Component
public final class CreationRateLimiter {
    private static final long SECOND = 1_000_000_000L;
    private static final long WINDOW = 60 * SECOND;

    public static final class LimitExceeded extends RuntimeException {
        private final long retryAfter;

        private LimitExceeded(long retryAfter) {
            super("Creation limit exceeded");
            this.retryAfter = retryAfter;
        }

        public long retryAfter() { return retryAfter; }
    }

    private final int limit;
    private final LongSupplier nanoTime;
    private long started;
    private int admitted;

    @Autowired
    public CreationRateLimiter(@Value("${shortener.creation-limit-per-minute:20}") int limit) {
        this(limit, System::nanoTime);
    }

    CreationRateLimiter(int limit, LongSupplier nanoTime) {
        if (limit < 1) throw new IllegalArgumentException("Invalid creation limit configuration");
        this.limit = limit;
        this.nanoTime = Objects.requireNonNull(nanoTime);
    }

    public synchronized void admit() {
        long now = nanoTime.getAsLong();
        long elapsed = now - started;
        if (admitted == 0 || elapsed >= WINDOW) {
            started = now;
            admitted = 0;
            elapsed = 0;
        }
        if (admitted == limit) {
            long remaining = WINDOW - elapsed;
            throw new LimitExceeded(Math.max(1, (remaining + SECOND - 1) / SECOND));
        }
        admitted++;
    }
}

package com.urlshortner.urls;

import java.net.URI;
import java.net.URISyntaxException;

final class Destination {
    private Destination() {}

    static boolean valid(String value) {
        if (value == null || value.isBlank()) return false;
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            if (Character.isISOControl(c)) return false;
            if (c == '%' && i + 2 < value.length()) {
                int high = Character.digit(value.charAt(i + 1), 16);
                int low = Character.digit(value.charAt(i + 2), 16);
                if (high >= 0 && low >= 0 && Character.isISOControl((char) (high * 16 + low))) {
                    return false;
                }
            }
        }
        try {
            URI uri = new URI(value).parseServerAuthority();
            String scheme = uri.getScheme();
            if (!("http".equalsIgnoreCase(scheme) || "https".equalsIgnoreCase(scheme))) return false;
            if (uri.getHost() == null || uri.getHost().isBlank() || uri.getRawUserInfo() != null) return false;
            if (uri.getPort() < -1 || uri.getPort() > 65535) return false;
            // URI accepts an empty explicit port; reject it as malformed authority.
            return !uri.getRawAuthority().endsWith(":");
        } catch (URISyntaxException | IllegalArgumentException exception) {
            return false;
        }
    }
}

