import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.DispatcherType;
import jakarta.servlet.RequestDispatcher;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;
import org.slf4j.MDC;
import org.springframework.http.HttpHeaders;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;
import org.springframework.web.HttpRequestMethodNotSupportedException;
import org.springframework.web.HttpMediaTypeNotSupportedException;
import org.springframework.web.servlet.resource.NoResourceFoundException;
import org.springframework.http.HttpMethod;
import static org.junit.jupiter.api.Assertions.*;

class ErrorHandlingTest {
    private final ObjectMapper mapper = new ObjectMapper();
    private final Logger logger = (Logger) LoggerFactory.getLogger(RequestEvents.class);
    private final ListAppender<ILoggingEvent> appender = new ListAppender<>();
    private Level previousLevel;
    private Map<String, String> previousMdc;

    @BeforeEach
    void capture() {
        previousLevel = logger.getLevel();
        previousMdc = MDC.getCopyOfContextMap();
        MDC.clear();
        logger.setLevel(Level.DEBUG);
        appender.start();
        logger.addAppender(appender);
    }

    @AfterEach
    void restore() {
        logger.detachAppender(appender);
        appender.stop();
        logger.setLevel(previousLevel);
        if (previousMdc == null) MDC.clear();
        else MDC.setContextMap(previousMdc);
    }

    private MockHttpServletRequest request(String method, String path) {
        MockHttpServletRequest request = new MockHttpServletRequest(method, path);
        request.setServletPath(path);
        request.setQueryString("visitor=PRIVATE_VISITOR");
        request.addHeader("Authorization", "PRIVATE_CREDENTIAL");
        request.addHeader("X-Request-ID", "PRIVATE_VISITOR");
        return request;
    }

    private void envelope(MockHttpServletRequest request, MockHttpServletResponse response,
            int status, String code, String message, Instant before) throws Exception {
        assertEquals(status, response.getStatus());
        assertTrue(response.getContentType().startsWith("application/json"));
        var body = mapper.readTree(response.getContentAsString());
        assertEquals(5, body.size());
        assertEquals(code, body.get("code").asText());
        assertEquals(message, body.get("message").asText());
        assertEquals(RequestEvents.path(request), body.get("path").asText());
        String id = response.getHeader("X-Request-ID");
        UUID.fromString(id);
        assertEquals(id, body.get("requestId").asText());
        assertNotEquals("PRIVATE_VISITOR", id);
        String timestamp = body.get("timestamp").asText();
        assertTrue(timestamp.endsWith("Z"));
        Instant instant = Instant.parse(timestamp);
        assertFalse(instant.isBefore(before));
        assertFalse(instant.isAfter(Instant.now()));
        assertFalse(response.getContentAsString().contains("PRIVATE_"));
    }

    @Test
    void allApplicationErrorsHaveSafeCorrelatedEnvelopesAndRestoreMdc() throws Exception {
        CreationRateLimiter limiter = new CreationRateLimiter(1, () -> 0L);
        limiter.admit();
        Exception limited = assertThrows(CreationRateLimiter.LimitExceeded.class, limiter::admit);
        Exception[] failures = {new InvalidCreationRequest(), new UrlService.UnknownCode(),
                new UrlService.ExpiredCode(), limited, new UrlService.AllocationExhausted(),
                new IllegalArgumentException("PRIVATE_CREDENTIAL https://PRIVATE_DESTINATION", new RuntimeException("PRIVATE_VISITOR"))};
        int[] statuses = {400, 404, 410, 429, 503, 500};
        String[] codes = {"INVALID_INPUT", "LINK_NOT_FOUND", "LINK_EXPIRED", "RATE_LIMITED", "CODE_ALLOCATION_UNAVAILABLE", "INTERNAL_ERROR"};
        String[] messages = {"Invalid creation request", "Unknown code", "Expired code", "Creation limit exceeded", "Code allocation unavailable", "Internal server error"};
        for (int i = 0; i < failures.length; i++) {
            var request = request("GET", "/r/link");
            var response = new MockHttpServletResponse();
            Exception failure = failures[i];
            MDC.put("requestId", "outer");
            MDC.put("worker", "retained");
            Instant before = Instant.now();
            int count = appender.list.size();
            new RequestCorrelationFilter().doFilter(request, response, (req, res) -> {
                assertEquals(request.getAttribute(RequestEvents.ID), MDC.get("requestId"));
                var entity = new UrlErrors().handle(failure, request);
                response.setStatus(entity.getStatusCode().value());
                entity.getHeaders().forEach((name, values) -> values.forEach(value -> response.addHeader(name, value)));
                response.setContentType("application/json");
                response.getWriter().write(mapper.writeValueAsString(entity.getBody()));
            });
            envelope(request, response, statuses[i], codes[i], messages[i], before);
            assertEquals("outer", MDC.get("requestId"));
            assertEquals("retained", MDC.get("worker"));
            assertEquals(count + 1, appender.list.size());
            ILoggingEvent event = appender.list.getLast();
            assertEquals(i == 5 ? Level.ERROR : Level.WARN, event.getLevel());
            assertEquals(response.getHeader("X-Request-ID"), field(event, "requestId"));
            assertEquals("redirect", field(event, "operation"));
            assertEquals("failure", field(event, "outcome"));
            assertEquals(codes[i], field(event, "errorCode"));
            if (i == 3) assertEquals("60", response.getHeader("Retry-After"));
        }
        assertPrivateDataAbsent();
    }

    @Test
    void nativeFrameworkStatusesAndHeadersArePreserved() {
        var request = request("POST", "/other");
        var method = ErrorPolicy.response(request,
                new HttpRequestMethodNotSupportedException("POST", java.util.List.of("GET")));
        assertEquals(405, method.getStatusCode().value());
        assertEquals("GET", method.getHeaders().getFirst(HttpHeaders.ALLOW));
        assertEquals("INVALID_INPUT", method.getBody().code());
        assertEquals(415, ErrorPolicy.response(request,
                new HttpMediaTypeNotSupportedException("private content")).getStatusCode().value());
        assertEquals(404, ErrorPolicy.response(request,
                new NoResourceFoundException(HttpMethod.GET, "PRIVATE_VISITOR")).getStatusCode().value());
        assertPrivateDataAbsent();
    }

    @Test
    void escapingFilterFailureUsesSharedEnvelopeAndCleansContext() throws Exception {
        var request = request("GET", "/r/link");
        var response = new MockHttpServletResponse();
        Instant before = Instant.now();
        new RequestCorrelationFilter().doFilter(request, response, (req, res) -> {
            throw new IllegalStateException("PRIVATE_CREDENTIAL", new RuntimeException("https://PRIVATE_DESTINATION"));
        });
        envelope(request, response, 500, "INTERNAL_ERROR", "Internal server error", before);
        assertNull(MDC.get("requestId"));
        assertEquals(1, appender.list.size());
        assertEquals(Level.ERROR, appender.list.getFirst().getLevel());
        assertPrivateDataAbsent();
    }

    @Test
    void committedFailuresDoNotRewriteBodyOrLogTwiceDuringErrorDispatch() throws Exception {
        var request = request("GET", "/r/link");
        var response = new MockHttpServletResponse();
        new RequestCorrelationFilter().doFilter(request, response, (req, res) -> {
            response.setStatus(302);
            response.getWriter().write("already written");
            response.flushBuffer();
            throw new IllegalStateException("PRIVATE_VISITOR");
        });
        assertEquals(302, response.getStatus());
        assertEquals("already written", response.getContentAsString());
        assertEquals(1, appender.list.size());
        request.setDispatcherType(DispatcherType.ERROR);
        request.setAttribute(RequestDispatcher.ERROR_STATUS_CODE, 500);
        assertNull(new ServletErrors().error(request, response));
        assertEquals(1, appender.list.size());
        assertNull(MDC.get("requestId"));
        assertPrivateDataAbsent();
    }

    @Test
    void servletErrorDispatchRetainsOriginalPathRequestIdAndSingleFailure() throws Exception {
        var request = request("GET", "/error");
        request.setDispatcherType(DispatcherType.ERROR);
        request.setAttribute(RequestDispatcher.ERROR_REQUEST_URI, "/original");
        request.setAttribute(RequestDispatcher.ERROR_STATUS_CODE, 404);
        request.setAttribute(RequestEvents.ID, UUID.randomUUID().toString());
        var response = new MockHttpServletResponse();
        Instant before = Instant.now();
        new RequestCorrelationFilter().doFilter(request, response, (req, res) -> {
            var entity = new ServletErrors().error(request, response);
            response.setStatus(entity.getStatusCode().value());
            response.setContentType("application/json");
            response.getWriter().write(mapper.writeValueAsString(entity.getBody()));
        });
        envelope(request, response, 404, "LINK_NOT_FOUND", "Resource not found", before);
        assertEquals(1, appender.list.size());
        assertNull(MDC.get("requestId"));
    }

    @Test
    void successesAndDiagnosticsRespectConfiguredSeverityAndHaveFixedFields() throws Exception {
        for (String operation : new String[] {"create", "redirect", "analytics"}) {
            String path = operation.equals("create") ? "/api/urls" : operation.equals("redirect") ? "/r/PRIVATE_VISITOR" : "/api/urls/PRIVATE_VISITOR/analytics";
            var request = request(operation.equals("create") ? "POST" : "GET", path);
            var response = new MockHttpServletResponse();
            new RequestCorrelationFilter().doFilter(request, response, (req, res) -> {
                response.setStatus(operation.equals("create") ? 201 : operation.equals("redirect") ? 302 : 200);
            });
            var event = appender.list.getLast();
            assertEquals(operation.equals("analytics") ? Level.DEBUG : Level.INFO, event.getLevel());
            assertEquals(operation, field(event, "operation"));
            assertEquals("success", field(event, "outcome"));
            assertEquals(response.getHeader("X-Request-ID"), field(event, "requestId"));
        }
        MDC.put("requestId", UUID.randomUUID().toString());
        RequestEvents.collision(1);
        assertEquals(Level.DEBUG, appender.list.getLast().getLevel());
        int count = appender.list.size();
        logger.setLevel(Level.INFO);
        RequestEvents.collision(2);
        assertEquals(count, appender.list.size());
        assertPrivateDataAbsent();
    }

    @Test
    void diagnosticTraversalIsBoundedAndCycleSafe() {
        RuntimeException first = new RuntimeException("PRIVATE_CREDENTIAL");
        RuntimeException second = new RuntimeException("PRIVATE_VISITOR");
        first.initCause(second);
        second.initCause(first);
        first.addSuppressed(new RuntimeException("https://PRIVATE_DESTINATION"));
        String diagnostic = RequestEvents.diagnostic(first);
        assertTrue(diagnostic.contains("java.lang.RuntimeException"));
        assertFalse(diagnostic.contains("PRIVATE_"));
        assertTrue(diagnostic.length() < 5000);
    }

    private Object field(ILoggingEvent event, String key) {
        return event.getKeyValuePairs().stream().filter(pair -> pair.key.equals(key))
                .map(pair -> pair.value).findFirst().orElseThrow();
    }

    private void assertPrivateDataAbsent() {
        for (ILoggingEvent event : appender.list) {
            assertNull(event.getThrowableProxy());
            assertFalse(event.getFormattedMessage().contains("PRIVATE_"));
            assertFalse(event.getMDCPropertyMap().toString().contains("PRIVATE_"));
            assertFalse(String.valueOf(event.getKeyValuePairs()).contains("PRIVATE_"));
            assertFalse(String.valueOf(event.getKeyValuePairs()).contains("https://"));
        }
    }
}

package com.urlshortner.urls;

import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ExpiryCapTest {
    @ParameterizedTest
    @ValueSource(longs = {7, 30, 31, 365, Long.MAX_VALUE})
    void configuredLimitCannotExceedSevenDays(long configuredDays) {
        Instant now = Instant.parse("2026-01-01T00:00:00.123456789Z");
        UrlRepository repository = mock(UrlRepository.class);
        CodeGenerator codes = mock(CodeGenerator.class);
        UrlService service = new UrlService(repository, codes,
                Clock.fixed(now, ZoneOffset.UTC), configuredDays);
        String url = "https://example.com";
        Instant maximum = now.plus(Duration.ofDays(7));

        assertThrows(IllegalArgumentException.class, () -> service.create(url, maximum.plusNanos(1)));
        assertThrows(IllegalArgumentException.class,
                () -> service.create(url, now.plus(Duration.ofDays(30))));
        verifyNoInteractions(repository, codes);

        var saved = new UrlRepository.StoredUrl("Ab12Cd34", url, now, 0, null, maximum);
        when(codes.next()).thenReturn(saved.code());
        when(repository.insert(saved.code(), url, maximum)).thenReturn(saved);
        assertSame(saved, service.create(url, maximum));
        verify(repository).insert(saved.code(), url, maximum);
        verify(codes).next();
        verifyNoMoreInteractions(repository, codes);
    }

    @ParameterizedTest
    @ValueSource(longs = {0, -1, Long.MIN_VALUE})
    void rejectsNonpositiveConfiguration(long configuredDays) {
        assertThrows(IllegalArgumentException.class, () -> new UrlService(
                mock(UrlRepository.class), mock(CodeGenerator.class), Clock.systemUTC(), configuredDays));
    }
}

package com.urlshortner.urls;

import com.fasterxml.jackson.databind.SerializationFeature;
import com.urlshortner.InjectedRedirectFaultFilter;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.http.MediaType;
import org.springframework.http.converter.json.Jackson2ObjectMapperBuilder;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class ExpiryHttpBoundaryTest {
    private static final Instant T = Instant.parse("2026-01-01T00:00:00.123456789Z");
    private static final String URL = "https://example.com/a?b=1#part";
    private final UrlRepository repository = mock(UrlRepository.class);
    private final CodeGenerator codes = mock(CodeGenerator.class);
    private final Clock clock = mock(Clock.class);
    private final LocalValidatorFactoryBean validator = new LocalValidatorFactoryBean();
    private MockMvc mvc;

    @BeforeEach
    void setup() {
        validator.afterPropertiesSet();
        var mapper = Jackson2ObjectMapperBuilder.json()
                .featuresToDisable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).build();
        var service = new UrlService(repository, codes, clock, 30);
        mvc = MockMvcBuilders.standaloneSetup(new UrlController(service, "https://public.example/links/"))
                .setControllerAdvice(new UrlErrors()).setValidator(validator)
                .addFilters(new InjectedRedirectFaultFilter())
                .setMessageConverters(new MappingJackson2HttpMessageConverter(mapper)).build();
        when(clock.instant()).thenReturn(T, T.plus(Duration.ofDays(20)));
    }

    @AfterEach
    void close() { validator.close(); }

    @ParameterizedTest
    @ValueSource(longs = {-1, 0, 604800000000001L})
    void invalidBoundariesReturn400BeforeAllocation(long nanos) throws Exception {
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + URL + "\",\"expiresAt\":\"" + T.plusNanos(nanos) + "\"}"))
                .andExpect(status().isBadRequest());
        verify(clock).instant();
        verifyNoInteractions(repository, codes);
    }

    @ParameterizedTest
    @ValueSource(longs = {1, 604800000000000L})
    void validBoundariesUseOneInstantAndPreserveFields(long nanos) throws Exception {
        Instant expiry = T.plusNanos(nanos);
        var saved = new UrlRepository.StoredUrl("Ab12Cd34", URL, T, 0, null, expiry);
        when(codes.next()).thenReturn(saved.code());
        when(repository.insert(saved.code(), URL, expiry)).thenReturn(saved);
        mvc.perform(post("/api/urls").header("Host", "attacker.example")
                        .header("Forwarded", "proto=http;host=attacker.example")
                        .header("X-Forwarded-Host", "attacker.example")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + URL + "\",\"expiresAt\":\"" + expiry + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "https://public.example/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.code").value(saved.code()))
                .andExpect(jsonPath("$.shortUrl").value("https://public.example/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.url").value(URL))
                .andExpect(jsonPath("$.createdAt").value(T.toString()))
                .andExpect(jsonPath("$.expiresAt").value(expiry.toString()));
        verify(clock).instant();
        verify(repository).insert(saved.code(), URL, expiry);
    }
}

package com.urlshortner.urls;

import com.fasterxml.jackson.databind.SerializationFeature;
import com.urlshortner.InjectedRedirectFaultFilter;
import java.time.Instant;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.http.MediaType;
import org.springframework.http.converter.json.Jackson2ObjectMapperBuilder;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
import static org.hamcrest.Matchers.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class UrlControllerTest {
    private final UrlService service = mock(UrlService.class);
    private final LocalValidatorFactoryBean validator = new LocalValidatorFactoryBean();
    private final Instant created = Instant.parse("2026-01-01T00:00:00Z");
    private MockMvc mvc;

    @BeforeEach
    void setup() {
        validator.afterPropertiesSet();
        mvc = mvcFor("https://public.example:8443/links/");
    }

    private MockMvc mvcFor(String base) {
        var mapper = Jackson2ObjectMapperBuilder.json()
                .featuresToDisable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).build();
        return MockMvcBuilders.standaloneSetup(new UrlController(service, base))
                .setControllerAdvice(new UrlErrors()).setValidator(validator)
                .addFilters(new RequestCorrelationFilter(), new InjectedRedirectFaultFilter())
                .setMessageConverters(new MappingJackson2HttpMessageConverter(mapper)).build();
    }

    @AfterEach
    void close() { validator.close(); }

    private UrlRepository.StoredUrl saved(Instant expiry) {
        return new UrlRepository.StoredUrl("Ab12Cd34", "https://example.com/a?b=1#part", created, 0, null, expiry);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", ",\"expiresAt\":null"})
    void omittedAndNullExpiryPreserveConfiguredPublicUrl(String suffix) throws Exception {
        var saved = saved(null);
        when(service.create(saved.url(), null)).thenReturn(saved);
        mvc.perform(post("/app/api/urls").contextPath("/app")
                        .header("Host", "attacker.example")
                        .header("Forwarded", "proto=http;host=attacker.example")
                        .header("X-Forwarded-Host", "attacker.example")
                        .header("X-Forwarded-Proto", "http")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + saved.url() + "\"" + suffix + "}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "https://public.example:8443/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.shortUrl").value("https://public.example:8443/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.code").value(saved.code()))
                .andExpect(jsonPath("$.url").value(saved.url()))
                .andExpect(jsonPath("$.createdAt").value(created.toString()))
                .andExpect(jsonPath("$", hasKey("expiresAt")))
                .andExpect(jsonPath("$.expiresAt").value(nullValue()));
        verify(service).create(saved.url(), null);
        verifyNoMoreInteractions(service);
    }

    @ParameterizedTest
    @ValueSource(strings = {"2026-01-02T00:00:00.123456789Z", "2026-01-02T00:00:00.123456789+00:00"})
    void exposesExactExpiryOnCreationAndAnalytics(String text) throws Exception {
        Instant expiry = Instant.parse("2026-01-02T00:00:00.123456789Z");
        var saved = saved(expiry);
        when(service.create(saved.url(), expiry)).thenReturn(saved);
        when(service.analytics(saved.code())).thenReturn(saved);
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + saved.url() + "\",\"expiresAt\":\"" + text + "\"}"))
                .andExpect(status().isCreated()).andExpect(jsonPath("$.expiresAt").value(expiry.toString()));
        mvc.perform(get("/api/urls/Ab12Cd34/analytics"))
                .andExpect(status().isOk()).andExpect(jsonPath("$.expiresAt").value(expiry.toString()))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andExpect(jsonPath("$.lastAccessedAt").value(nullValue()));
    }

    @ParameterizedTest
    @ValueSource(strings = {"42", "true", "[]", "{}", "\"\"", "\"bad\"",
            "\"2026-01-02T00:00:00\"", "\"2026-01-02T01:00:00+01:00\""})
    void rejectsExpiryTypesAndNonUtcValues(String expiry) throws Exception {
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"https://example.com\",\"expiresAt\":" + expiry + "}"))
                .andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_INPUT"));
        verifyNoInteractions(service);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "{", "null", "[]", "{}", "{\"url\":null}",
            "{\"url\":42}", "{\"url\":true}", "{\"url\":{}}", "{\"url\":[]}",
            "{\"url\":\"\"}", "{\"url\":\"ftp://example.com\"}",
            "{\"url\":\"https://user@example.com\"}", "{\"url\":\"https://example.com/\\r\\n\"}"})
    void invalidBodiesDoNotCallService(String body) throws Exception {
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_INPUT"));
        verifyNoInteractions(service);
    }

    @Test
    void redirectsAndMapsErrorsWithoutLeakingDetails() throws Exception {
        when(service.redirect("valid")).thenReturn("https://example.com/a?b=1#part");
        when(service.redirect("expired")).thenThrow(new UrlService.ExpiredCode());
        when(service.redirect("missing")).thenThrow(new UrlService.UnknownCode());
        when(service.analytics("missing")).thenThrow(new UrlService.UnknownCode());
        when(service.analytics("broken")).thenThrow(new IllegalStateException("private SQL"));
        mvc.perform(get("/r/valid")).andExpect(status().isFound())
                .andExpect(header().string("Location", "https://example.com/a?b=1#part"));
        mvc.perform(get("/r/expired")).andExpect(status().isGone()).andExpect(header().doesNotExist("Location"))
                .andExpect(jsonPath("$.code").value("LINK_EXPIRED"));
        mvc.perform(get("/r/missing")).andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"))
                .andExpect(jsonPath("$.code").value("LINK_NOT_FOUND"));
        mvc.perform(get("/api/urls/missing/analytics")).andExpect(status().isNotFound());
        mvc.perform(get("/api/urls/broken/analytics")).andExpect(status().isInternalServerError())
                .andExpect(jsonPath("$.code").value("INTERNAL_ERROR"))
                .andExpect(jsonPath("$.message").value("Internal server error"));
        verify(service).redirect("valid");
    }

    @Test
    void nonExpiringAnalyticsIncludesExplicitNullAndRecordedAccess() throws Exception {
        when(service.analytics("Ab12Cd34")).thenReturn(new UrlRepository.StoredUrl(
                "Ab12Cd34", "https://example.com", created, 12, created.plusSeconds(1), null));
        mvc.perform(get("/api/urls/Ab12Cd34/analytics")).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(12))
                .andExpect(jsonPath("$.lastAccessedAt").value(created.plusSeconds(1).toString()))
                .andExpect(jsonPath("$", hasKey("expiresAt")))
                .andExpect(jsonPath("$.expiresAt").value(nullValue()));
        verify(service).analytics("Ab12Cd34");
        verifyNoMoreInteractions(service);
    }

    @Test
    void creationServiceValidationAndExhaustionMapToExpectedStatuses() throws Exception {
        doThrow(new InvalidCreationRequest()).when(service).create("https://example.com", null);
        String body = "{\"url\":\"https://example.com\"}";
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("INVALID_INPUT"));
        doThrow(new UrlService.AllocationExhausted()).when(service).create("https://example.com", null);
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isServiceUnavailable())
                .andExpect(jsonPath("$.code").value("CODE_ALLOCATION_UNAVAILABLE"));
        doThrow(new IllegalArgumentException("private failure")).when(service).create("https://example.com", null);
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isInternalServerError()).andExpect(jsonPath("$.code").value("INTERNAL_ERROR"));
    }

    @ParameterizedTest
    @ValueSource(strings = {"http://127.0.0.1:8000", "http://127.0.0.1:8000/"})
    void rootBaseHasOneSeparator(String base) throws Exception {
        when(service.create("https://example.com", null)).thenReturn(saved(null));
