import java.time.Duration;
import java.time.Instant;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.http.MediaType;
import org.springframework.http.converter.json.Jackson2ObjectMapperBuilder;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class ExpiryHttpBoundaryTest {
    private static final Instant T = Instant.parse("2026-01-01T00:00:00.123456789Z");
    private static final String URL = "https://example.com/a?b=1#part";
    private final UrlRepository repository = mock(UrlRepository.class);
    private final CodeGenerator codes = mock(CodeGenerator.class);
    private final Clock clock = mock(Clock.class);
    private final LocalValidatorFactoryBean validator = new LocalValidatorFactoryBean();
    private MockMvc mvc;

    @BeforeEach
    void setup() {
        validator.afterPropertiesSet();
        var mapper = Jackson2ObjectMapperBuilder.json()
                .featuresToDisable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).build();
        var service = new UrlService(repository, codes, clock, 30);
        mvc = MockMvcBuilders.standaloneSetup(new UrlController(service, "https://public.example/links/"))
                .setControllerAdvice(new UrlErrors()).setValidator(validator)
                .addFilters(new InjectedRedirectFaultFilter())
                .setMessageConverters(new MappingJackson2HttpMessageConverter(mapper)).build();
        when(clock.instant()).thenReturn(T, T.plus(Duration.ofDays(20)));
    }

    @AfterEach
    void close() { validator.close(); }

    @ParameterizedTest
    @ValueSource(longs = {-1, 0, 604800000000001L})
    void invalidBoundariesReturn400BeforeAllocation(long nanos) throws Exception {
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + URL + "\",\"expiresAt\":\"" + T.plusNanos(nanos) + "\"}"))
                .andExpect(status().isBadRequest());
        verify(clock).instant();
        verifyNoInteractions(repository, codes);
    }

    @ParameterizedTest
    @ValueSource(longs = {1, 604800000000000L})
    void validBoundariesUseOneInstantAndPreserveFields(long nanos) throws Exception {
        Instant expiry = T.plusNanos(nanos);
        var saved = new UrlRepository.StoredUrl("Ab12Cd34", URL, T, 0, null, expiry);
        when(codes.next()).thenReturn(saved.code());
        when(repository.insert(saved.code(), URL, expiry)).thenReturn(saved);
        mvc.perform(post("/api/urls").header("Host", "attacker.example")
                        .header("Forwarded", "proto=http;host=attacker.example")
                        .header("X-Forwarded-Host", "attacker.example")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + URL + "\",\"expiresAt\":\"" + expiry + "\"}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "https://public.example/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.code").value(saved.code()))
                .andExpect(jsonPath("$.shortUrl").value("https://public.example/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.url").value(URL))
                .andExpect(jsonPath("$.createdAt").value(T.toString()))
                .andExpect(jsonPath("$.expiresAt").value(expiry.toString()));
        verify(clock).instant();
        verify(repository).insert(saved.code(), URL, expiry);
    }
}

package com.urlshortner.urls;

import com.fasterxml.jackson.databind.SerializationFeature;
import com.urlshortner.InjectedRedirectFaultFilter;
import java.time.Instant;
import org.junit.jupiter.api.*;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.http.MediaType;
import org.springframework.http.converter.json.Jackson2ObjectMapperBuilder;
import org.springframework.http.converter.json.MappingJackson2HttpMessageConverter;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import org.springframework.validation.beanvalidation.LocalValidatorFactoryBean;
import static org.hamcrest.Matchers.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

class UrlControllerTest {
    private final UrlService service = mock(UrlService.class);
    private final LocalValidatorFactoryBean validator = new LocalValidatorFactoryBean();
    private final Instant created = Instant.parse("2026-01-01T00:00:00Z");
    private MockMvc mvc;

    @BeforeEach
    void setup() {
        validator.afterPropertiesSet();
        mvc = mvcFor("https://public.example:8443/links/");
    }

    private MockMvc mvcFor(String base) {
        var mapper = Jackson2ObjectMapperBuilder.json()
                .featuresToDisable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).build();
        return MockMvcBuilders.standaloneSetup(new UrlController(service, base))
                .setControllerAdvice(new UrlErrors()).setValidator(validator)
                .addFilters(new InjectedRedirectFaultFilter())
                .setMessageConverters(new MappingJackson2HttpMessageConverter(mapper)).build();
    }

    @AfterEach
    void close() { validator.close(); }

    private UrlRepository.StoredUrl saved(Instant expiry) {
        return new UrlRepository.StoredUrl("Ab12Cd34", "https://example.com/a?b=1#part", created, 0, null, expiry);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", ",\"expiresAt\":null"})
    void omittedAndNullExpiryPreserveConfiguredPublicUrl(String suffix) throws Exception {
        var saved = saved(null);
        when(service.create(saved.url(), null)).thenReturn(saved);
        mvc.perform(post("/app/api/urls").contextPath("/app")
                        .header("Host", "attacker.example")
                        .header("Forwarded", "proto=http;host=attacker.example")
                        .header("X-Forwarded-Host", "attacker.example")
                        .header("X-Forwarded-Proto", "http")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + saved.url() + "\"" + suffix + "}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "https://public.example:8443/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.shortUrl").value("https://public.example:8443/links/r/Ab12Cd34"))
                .andExpect(jsonPath("$.code").value(saved.code()))
                .andExpect(jsonPath("$.url").value(saved.url()))
                .andExpect(jsonPath("$.createdAt").value(created.toString()))
                .andExpect(jsonPath("$", hasKey("expiresAt")))
                .andExpect(jsonPath("$.expiresAt").value(nullValue()));
        verify(service).create(saved.url(), null);
        verifyNoMoreInteractions(service);
    }

    @ParameterizedTest
    @ValueSource(strings = {"2026-01-02T00:00:00.123456789Z", "2026-01-02T00:00:00.123456789+00:00"})
    void exposesExactExpiryOnCreationAndAnalytics(String text) throws Exception {
        Instant expiry = Instant.parse("2026-01-02T00:00:00.123456789Z");
        var saved = saved(expiry);
        when(service.create(saved.url(), expiry)).thenReturn(saved);
        when(service.analytics(saved.code())).thenReturn(saved);
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"" + saved.url() + "\",\"expiresAt\":\"" + text + "\"}"))
                .andExpect(status().isCreated()).andExpect(jsonPath("$.expiresAt").value(expiry.toString()));
        mvc.perform(get("/api/urls/Ab12Cd34/analytics"))
                .andExpect(status().isOk()).andExpect(jsonPath("$.expiresAt").value(expiry.toString()))
                .andExpect(jsonPath("$.clickCount").value(0))
                .andExpect(jsonPath("$.lastAccessedAt").value(nullValue()));
    }

    @ParameterizedTest
    @ValueSource(strings = {"42", "true", "[]", "{}", "\"\"", "\"bad\"",
            "\"2026-01-02T00:00:00\"", "\"2026-01-02T01:00:00+01:00\""})
    void rejectsExpiryTypesAndNonUtcValues(String expiry) throws Exception {
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"https://example.com\",\"expiresAt\":" + expiry + "}"))
                .andExpect(status().isBadRequest());
        verifyNoInteractions(service);
    }

    @ParameterizedTest
    @ValueSource(strings = {"", "{", "null", "[]", "{}", "{\"url\":null}",
            "{\"url\":42}", "{\"url\":true}", "{\"url\":{}}", "{\"url\":[]}",
            "{\"url\":\"\"}", "{\"url\":\"ftp://example.com\"}",
            "{\"url\":\"https://user@example.com\"}", "{\"url\":\"https://example.com/\\r\\n\"}"})
    void invalidBodiesDoNotCallService(String body) throws Exception {
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isBadRequest());
        verifyNoInteractions(service);
    }

    @Test
    void redirectsAndMapsErrorsWithoutLeakingDetails() throws Exception {
        when(service.redirect("valid")).thenReturn("https://example.com/a?b=1#part");
        when(service.redirect("expired")).thenThrow(new UrlService.ExpiredCode());
        when(service.redirect("missing")).thenThrow(new UrlService.UnknownCode());
        when(service.analytics("missing")).thenThrow(new UrlService.UnknownCode());
        when(service.analytics("broken")).thenThrow(new IllegalStateException("private SQL"));
        mvc.perform(get("/r/valid")).andExpect(status().isFound())
                .andExpect(header().string("Location", "https://example.com/a?b=1#part"));
        mvc.perform(get("/r/expired")).andExpect(status().isGone()).andExpect(header().doesNotExist("Location"));
        mvc.perform(get("/r/missing")).andExpect(status().isNotFound()).andExpect(header().doesNotExist("Location"));
        mvc.perform(get("/api/urls/missing/analytics")).andExpect(status().isNotFound());
        mvc.perform(get("/api/urls/broken/analytics")).andExpect(status().isInternalServerError())
                .andExpect(content().json("{\"error\":\"Internal server error\"}"));
        verify(service).redirect("valid");
    }

    @Test
    void nonExpiringAnalyticsIncludesExplicitNullAndRecordedAccess() throws Exception {
        when(service.analytics("Ab12Cd34")).thenReturn(new UrlRepository.StoredUrl(
                "Ab12Cd34", "https://example.com", created, 12, created.plusSeconds(1), null));
        mvc.perform(get("/api/urls/Ab12Cd34/analytics")).andExpect(status().isOk())
                .andExpect(jsonPath("$.clickCount").value(12))
                .andExpect(jsonPath("$.lastAccessedAt").value(created.plusSeconds(1).toString()))
                .andExpect(jsonPath("$", hasKey("expiresAt")))
                .andExpect(jsonPath("$.expiresAt").value(nullValue()));
        verify(service).analytics("Ab12Cd34");
        verifyNoMoreInteractions(service);
    }

    @Test
    void creationServiceValidationAndExhaustionMapToExpectedStatuses() throws Exception {
        doThrow(new IllegalArgumentException()).when(service).create("https://example.com", null);
        String body = "{\"url\":\"https://example.com\"}";
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isBadRequest());
        doThrow(new UrlService.AllocationExhausted()).when(service).create("https://example.com", null);
        mvc.perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isServiceUnavailable());
    }

    @ParameterizedTest
    @ValueSource(strings = {"http://127.0.0.1:8000", "http://127.0.0.1:8000/"})
    void rootBaseHasOneSeparator(String base) throws Exception {
        when(service.create("https://example.com", null)).thenReturn(saved(null));
        mvcFor(base).perform(post("/api/urls").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"url\":\"https://example.com\"}"))
                .andExpect(header().string("Location", "http://127.0.0.1:8000/r/Ab12Cd34"));
    }

    @ParameterizedTest
    @ValueSource(strings = {"/relative", "ftp://example.com", "https://user@example.com",
            "https://example.com/?query=1", "https://example.com/#fragment"})
    void rejectsInvalidPublicBase(String base) {
        assertThrows(IllegalArgumentException.class, () -> new UrlController(service, base));
    }
}

package com.urlshortner.urls;

import java.sql.ResultSet;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.mockito.ArgumentCaptor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class UrlRepositoryTest {
    @Test
    @SuppressWarnings({"unchecked", "rawtypes"})
    void mapsNullAndExactFractionalExpiryWithoutRounding() throws Exception {
        JdbcTemplate jdbc = mock(JdbcTemplate.class);
        UrlRepository repository = new UrlRepository(jdbc);
        ArgumentCaptor<RowMapper<UrlRepository.StoredUrl>> mapper = ArgumentCaptor.forClass((Class) RowMapper.class);
        when(jdbc.query(anyString(), any(RowMapper.class), eq("Ab12Cd34"))).thenReturn(List.of());
        repository.find("Ab12Cd34");
        verify(jdbc).query(contains("FROM url_service.urls"), mapper.capture(), eq("Ab12Cd34"));
        ResultSet rs = mock(ResultSet.class);
        Instant expiry = Instant.parse("2026-01-02T00:00:00.123456789Z");
        when(rs.getString("code")).thenReturn("Ab12Cd34");
        when(rs.getString("url")).thenReturn("https://example.com");
        when(rs.getObject("created_at", OffsetDateTime.class)).thenReturn(expiry.atOffset(ZoneOffset.UTC));
        assertNull(mapper.getValue().mapRow(rs, 0).expiresAt());
        when(rs.getObject("expires_at", OffsetDateTime.class)).thenReturn(UrlRepository.micros(expiry));
        when(rs.getInt("expires_at_submicro")).thenReturn(789);
        assertEquals(expiry, mapper.getValue().mapRow(rs, 0).expiresAt());
        assertEquals(Instant.parse("2026-01-02T00:00:00.123456Z"), UrlRepository.micros(expiry).toInstant());
    }

    @Test
    @SuppressWarnings("unchecked")
    void insertSplitsExpiryAndRedirectUsesStrictAtomicPredicate() {
        JdbcTemplate jdbc = mock(JdbcTemplate.class);
        UrlRepository repository = new UrlRepository(jdbc);
        Instant now = Instant.parse("2026-01-02T00:00:00.123456789Z");
        repository.insert("Ab12Cd34", "https://example.com", now);
        verify(jdbc).queryForObject(contains("INSERT INTO url_service.urls"), any(RowMapper.class),
                eq("Ab12Cd34"), eq("https://example.com"), eq(UrlRepository.micros(now)), eq(789));
        when(jdbc.query(anyString(), any(RowMapper.class), any(), any(), any(), any(), any())).thenReturn(List.of());
        assertTrue(repository.recordRedirect("Ab12Cd34", now).isEmpty());
        ArgumentCaptor<String> sql = ArgumentCaptor.forClass(String.class);
        verify(jdbc).query(sql.capture(), any(RowMapper.class), eq(UrlRepository.micros(now)),
                eq("Ab12Cd34"), eq(UrlRepository.micros(now)), eq(UrlRepository.micros(now)), eq(789));
        assertTrue(sql.getValue().contains("UPDATE url_service.urls"));
        assertTrue(sql.getValue().contains("click_count = click_count + 1"));
        assertTrue(sql.getValue().contains("expires_at > ?"));
        assertTrue(sql.getValue().contains("expires_at = ? AND expires_at_submicro > ?"));
        assertTrue(sql.getValue().contains("expires_at IS NULL"));
    }
}

package com.urlshortner.urls;

import java.sql.SQLException;
import java.time.*;
import java.util.Optional;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessResourceFailureException;
import org.springframework.dao.DuplicateKeyException;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class UrlServiceTest {
    private static final Instant T = Instant.parse("2026-01-01T00:00:00.123456789Z");
    private static final String URL = "https://example.com/a";
    private final UrlRepository repository = mock(UrlRepository.class);
    private final CodeGenerator codes = mock(CodeGenerator.class);
    private final Clock clock = mock(Clock.class);
    private final UrlService service = new UrlService(repository, codes, clock, 30);

    private void setup() {
        when(clock.instant()).thenReturn(T);
        when(codes.next()).thenReturn("Ab12Cd34");
    }

    private UrlRepository.StoredUrl saved(Instant expiry) {
        return new UrlRepository.StoredUrl("Ab12Cd34", URL, T, 0, null, expiry);
    }

    private DuplicateKeyException conflict(String constraint, String state) throws Exception {
        Class<?> detailType = Class.forName("org.postgresql.util.ServerErrorMessage");
        Object detail = detailType.getConstructor(String.class).newInstance(
                "SERROR\0C" + state + "\0Mduplicate\0surl_service\0turls\0n" + constraint + "\0\0");
        SQLException sql = (SQLException) Class.forName("org.postgresql.util.PSQLException")
                .getConstructor(detailType).newInstance(detail);
        return new DuplicateKeyException("collision", sql);
    }

    @Test
    void acceptsNullOneNanosecondAndInclusiveMaximum() {
        setup();
        for (Instant expiry : new Instant[] {null, T.plusNanos(1), T.plus(Duration.ofDays(7))}) {
            var saved = saved(expiry);
            when(repository.insert("Ab12Cd34", URL, expiry)).thenReturn(saved);
            assertSame(saved, service.create(URL, expiry));
        }
        verify(clock, times(3)).instant();
    }

    @Test
    void rejectsInvalidExpiryBeforeAllocation() {
        setup();
        for (Instant expiry : new Instant[] {T.minusNanos(1), T, T.plus(Duration.ofDays(7)).plusNanos(1)}) {
            assertThrows(IllegalArgumentException.class, () -> service.create(URL, expiry));
        }
        assertThrows(IllegalArgumentException.class, () -> service.create("ftp://example.com", null));
        verifyNoInteractions(repository);
        verify(codes, never()).next();
    }

    @Test
    void configuredMaximumIsUsed() {
        setup();
        var configured = new UrlService(repository, codes, clock, 2);
        Instant maximum = T.plus(Duration.ofDays(2));
        assertThrows(IllegalArgumentException.class, () -> configured.create(URL, maximum.plusNanos(1)));
        verifyNoInteractions(repository);
        verify(codes, never()).next();
        var saved = saved(maximum);
        when(repository.insert("Ab12Cd34", URL, maximum)).thenReturn(saved);
        assertSame(saved, configured.create(URL, maximum));
    }

    @Test
    void retriesWithoutReadingClockAgainAndCanSucceedOnFifthAttempt() throws Exception {
        setup();
        when(clock.instant()).thenReturn(T, T.plus(Duration.ofDays(40)));
        Instant expiry = T.plusNanos(1);
        var saved = saved(expiry);
        var collision = conflict("pk_urls_code", "23505");
        when(repository.insert("Ab12Cd34", URL, expiry)).thenThrow(collision).thenThrow(collision)
                .thenThrow(collision).thenThrow(collision).thenReturn(saved);
        assertSame(saved, service.create(URL, expiry));
        verify(clock).instant();
        verify(codes, times(5)).next();
    }

    @Test
    void stopsAfterFiveCollisions() throws Exception {
        setup();
        when(repository.insert("Ab12Cd34", URL, null)).thenThrow(conflict("pk_urls_code", "23505"));
        assertThrows(UrlService.AllocationExhausted.class, () -> service.create(URL, null));
        verify(repository, times(5)).insert("Ab12Cd34", URL, null);
    }

    @Test
    void unrelatedFailuresAreNotRetried() throws Exception {
        setup();
        for (var failure : new org.springframework.dao.DataAccessException[] {
                conflict("other", "23505"), conflict("pk_urls_code", "23503"),
                new DuplicateKeyException("pk_urls_code", new SQLException("pk_urls_code", "23505")),
                new DataAccessResourceFailureException("unavailable")}) {
            reset(repository);
            when(repository.insert("Ab12Cd34", URL, null)).thenThrow(failure);
            assertSame(failure, assertThrows(failure.getClass(), () -> service.create(URL, null)));
            verify(repository).insert("Ab12Cd34", URL, null);
        }
    }

    @Test
    void successfulRedirectUsesOneAtomicOperation() {
        setup();
        when(repository.recordRedirect("Ab12Cd34", T)).thenReturn(Optional.of(URL));
        assertEquals(URL, service.redirect("Ab12Cd34"));
        verify(repository).recordRedirect("Ab12Cd34", T);
        verify(repository, never()).find(anyString());
        verify(clock).instant();
    }

    @Test
    void equalityAndPastExpiryAreGoneButAnalyticsRemainsAvailable() {
        setup();
        when(repository.recordRedirect("Ab12Cd34", T)).thenReturn(Optional.empty());
        for (Instant expiry : new Instant[] {T, T.minusNanos(1)}) {
            var saved = saved(expiry);
            when(repository.find("Ab12Cd34")).thenReturn(Optional.of(saved));
            assertThrows(UrlService.ExpiredCode.class, () -> service.redirect("Ab12Cd34"));
            assertSame(saved, service.analytics("Ab12Cd34"));
        }
        verify(repository, times(2)).recordRedirect("Ab12Cd34", T);
        verify(repository, never()).insert(anyString(), anyString(), any());
    }

    @Test
    void advancingClockPassesEqualityToAtomicAccounting() {
        setup();
        Instant expiry = T.plusNanos(1);
        when(clock.instant()).thenReturn(T, expiry, expiry.plusNanos(1));
        when(repository.recordRedirect("Ab12Cd34", T)).thenReturn(Optional.of(URL));
        when(repository.recordRedirect("Ab12Cd34", expiry)).thenReturn(Optional.empty());
        when(repository.recordRedirect("Ab12Cd34", expiry.plusNanos(1))).thenReturn(Optional.empty());
        when(repository.find("Ab12Cd34")).thenReturn(Optional.of(saved(expiry)));
        assertEquals(URL, service.redirect("Ab12Cd34"));
        assertThrows(UrlService.ExpiredCode.class, () -> service.redirect("Ab12Cd34"));
        assertThrows(UrlService.ExpiredCode.class, () -> service.redirect("Ab12Cd34"));
        verify(clock, times(3)).instant();
        verify(repository).recordRedirect("Ab12Cd34", T);
        verify(repository).recordRedirect("Ab12Cd34", expiry);
        verify(repository).recordRedirect("Ab12Cd34", expiry.plusNanos(1));
    }

    @Test
    void unknownCodesAreAbsent() {
        setup();
        when(repository.recordRedirect("missing", T)).thenReturn(Optional.empty());
        when(repository.find("missing")).thenReturn(Optional.empty());
        assertThrows(UrlService.UnknownCode.class, () -> service.redirect("missing"));
        assertThrows(UrlService.UnknownCode.class, () -> service.analytics("missing"));
        verify(repository).recordRedirect("missing", T);
    }

    @Test
    void analyticsDoesNotReadClockOrRecordRedirect() {
        var stored = saved(T.minusNanos(1));
        when(repository.find("Ab12Cd34")).thenReturn(Optional.of(stored));
        assertSame(stored, service.analytics("Ab12Cd34"));
        verify(repository).find("Ab12Cd34");
        verifyNoMoreInteractions(repository);
        verifyNoInteractions(clock, codes);
    }

    @Test
    void repositoryFailureCannotProduceSuccessfulRedirect() {
        when(clock.instant()).thenReturn(T);
        var failure = new DataAccessResourceFailureException("unavailable");
        when(repository.recordRedirect("Ab12Cd34", T)).thenThrow(failure);
        assertSame(failure, assertThrows(DataAccessResourceFailureException.class,
                () -> service.redirect("Ab12Cd34")));
        verify(repository).recordRedirect("Ab12Cd34", T);
        verifyNoMoreInteractions(repository);
        verify(clock).instant();
    }

    @Test
    void generatedCodesHaveRequiredAlphabetAndLength() {
        var generator = new CodeGenerator();
        for (int i = 0; i < 100; i++) assertTrue(generator.next().matches("[0-9A-Za-z]{8}"));
    }
}
